create table public.khld_guidance_session (
  id uuid primary key default gen_random_uuid(),
  municipality_id uuid not null references public.municipality(id) default public.my_municipality(),
  reference text,
  title text not null,
  start_date date not null,
  end_date date not null,
  applications_open date not null,
  applications_close date not null,
  description text not null,
  executing_entity text not null,
  topic_id uuid not null references public.ref_khld_session_topic(id),
  topic_other text,
  is_core boolean not null,
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_guidance_session_id_municipality_key unique (id, municipality_id),
  constraint khld_guidance_session_reference_key unique (municipality_id, reference),
  constraint khld_guidance_session_dates_in_order check (end_date >= start_date),
  constraint khld_guidance_session_window_in_order check (applications_close >= applications_open)
);
comment on table public.khld_guidance_session is 'FORM-14 -- Counseling Sessions (Counselling sessions). 0159.';
create trigger trg_khld_guidance_session_reference before insert on public.khld_guidance_session for each row execute function public.khld_assign_reference('GS', '2', 'start_date');
create trigger trg_khld_guidance_session_other before insert or update on public.khld_guidance_session for each row execute function public.guard_rmth_other('topic_id:ref_khld_session_topic:topic_other');

create table public.khld_enterprise_request (
  id uuid primary key default gen_random_uuid(),
