  nationality_id uuid not null references public.ref_khld_nationality(id),
  nationality_other text,
  disability_id uuid not null references public.ref_khld_disability(id),
  session_id uuid not null,
  has_business boolean not null,
  working_status_id uuid not null references public.ref_khld_working_status(id),
  product_type_id uuid not null references public.ref_khld_product_type(id),
  product_type_other text,
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_enterprise_request_id_municipality_key unique (id, municipality_id),
  constraint khld_enterprise_request_session_id_fkey foreign key (session_id, municipality_id) references public.khld_guidance_session(id, municipality_id)
);
create unique index khld_enterprise_request_person_session_live on public.khld_enterprise_request (person_id, session_id) where deleted_at is null;
comment on table public.khld_enterprise_request is 'FORM-15 -- Attendance Requests (Attendance requests). 0159.';
create trigger trg_khld_enterprise_request_other before insert or update on public.khld_enterprise_request for each row execute function public.guard_rmth_other('nationality_id:ref_khld_nationality:nationality_other', 'product_type_id:ref_khld_product_type:product_type_other');

create table public.khld_market (
  id uuid primary key default gen_random_uuid(),
  municipality_id uuid not null references public.municipality(id) default public.my_municipality(),
  reference text,
  name text not null,
  start_date date not null,
  end_date date not null,
  actual_days int not null,
  applications_open date not null,
  applications_close date not null,
  description text not null,
  has_sponsor boolean not null,
  sponsor_name text,
  kiosks_available int not null,
  occasion_id uuid not null references public.ref_khld_market_occasion(id),
  occasion_other text,
  status_id uuid not null references public.ref_khld_event_status(id),
  is_published boolean not null default false,
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_market_id_municipality_key unique (id, municipality_id),
  constraint khld_market_reference_key unique (municipality_id, reference),
  constraint khld_market_actual_days_min check (actual_days >= 0),
  constraint khld_market_kiosks_available_min check (kiosks_available >= 0),
  constraint khld_market_dates_in_order check (end_date >= start_date),
  constraint khld_market_window_in_order check (applications_close >= applications_open)
);
comment on table public.khld_market is 'FORM-16 -- Markets (Markets). 0159.';
create trigger trg_khld_market_reference before insert on public.khld_market for each row execute function public.khld_assign_reference('MKT', '2', 'start_date');
create trigger trg_khld_market_other before insert or update on public.khld_market for each row execute function public.guard_rmth_other('occasion_id:ref_khld_market_occasion:occasion_other');
create trigger trg_khld_market_rules before insert or update on public.khld_market for each row execute function public.guard_khld_rules();

