-- ── the standard triggers, RLS, the junctions' DELETE policy ─────────────
do $secure$
declare
  r record;
  v_writer text;
begin
  for r in select * from (values
    ('khld_focal_point', 'can_write', false),
    ('khld_partner', 'can_write', false),
    ('khld_partner_contact', 'can_write', false),
    ('khld_meeting', 'can_write', false),
    ('khld_rehab_report', 'can_write', false),
    ('khld_campaign', 'can_write', false),
    ('khld_activity', 'can_write', false),
    ('khld_activity_attendance', 'can_write', false),
    ('khld_committee_member', 'can_write', false),
    ('khld_committee_meeting', 'can_write', false),
    ('khld_volunteer', 'can_write', false),
    ('khld_volunteer_attendance', 'can_write', false),
    ('khld_guidance_session', 'can_write', false),
    ('khld_enterprise_request', 'can_write', false),
    ('khld_market', 'can_write', false),
    ('khld_vendor_application', 'can_write', false),
    ('khld_market_attendance', 'can_write', false),
    ('khld_park_survey', 'is_staff', false),
    ('khld_partner_survey', 'is_staff', false),
    ('khld_contribution', 'can_write', false),
    ('khld_milestone_record', 'can_write', false),
    ('khld_enterprise_support', 'can_write', false),
    ('khld_producer_survey', 'is_staff', false),
    ('khld_rehab_report_option', 'can_write', true),
    ('khld_campaign_option', 'can_write', true),
    ('khld_activity_attendance_option', 'can_write', true),
    ('khld_volunteer_option', 'can_write', true),
    ('khld_milestone_record_option', 'can_write', true),
    ('khld_meeting_partner', 'can_write', true),
    ('khld_activity_partner', 'can_write', true)
  ) as t(tbl, writer, is_child) loop
    v_writer := format('public.%I()', r.writer);
    if r.is_child then
      execute format('create trigger trg_%1$s_audit after insert or update or delete on public.%1$I '
                     'for each row execute function public.audit_row()', r.tbl);
    else
      perform public.attach_standard_triggers(r.tbl);
    end if;
    execute format('alter table public.%I enable row level security', r.tbl);
    execute format('create policy %1$s_read on public.%1$I for select to authenticated '
                   'using (public.can_see_municipality(municipality_id))', r.tbl);
    execute format('create policy %1$s_insert on public.%1$I for insert to authenticated '
                   'with check (%2$s and public.can_see_municipality(municipality_id))', r.tbl, v_writer);
    execute format('create policy %1$s_update on public.%1$I for update to authenticated '
                   'using (%2$s and public.can_see_municipality(municipality_id)) '
                   'with check (%2$s and public.can_see_municipality(municipality_id))', r.tbl, v_writer);
    if r.is_child then
      execute format('create policy %1$s_delete on public.%1$I for delete to authenticated '
                     'using (%2$s and public.can_see_municipality(municipality_id))', r.tbl, v_writer);
    end if;
  end loop;
end $secure$;

-- ── an index on every foreign key, and on municipality_id and created_by ──
do $index$
declare
  r record;
begin
  for r in
    select c.relname as tbl, a.attname as col
      from pg_class c join pg_namespace s on s.oid = c.relnamespace
      join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
     where s.nspname = 'public' and c.relkind = 'r' and c.relname like 'khld\_%'
       and c.relname not in ('khld_reference_counter', 'khld_question_list', 'khld_file_field', 'khld_field_rule')
       and (a.attname in ('municipality_id', 'created_by')
            or exists (select 1 from pg_constraint k where k.conrelid = c.oid and k.contype = 'f' and k.conkey[1] = a.attnum))
       and not exists (select 1 from pg_index i where i.indrelid = c.oid and i.indkey[0] = a.attnum)
     order by 1, 2
  loop
    execute format('create index %I on public.%I (%I)', r.tbl || '_' || r.col || '_idx', r.tbl, r.col);
  end loop;
end $index$;

-- ── verification ─────────────────────────────────────────────────────────
do $verify$
declare
  v_n   int;
  v_bad text;
begin
  select count(*), string_agg(c.relname, ', ') into v_n, v_bad
    from pg_class c join pg_namespace s on s.oid = c.relnamespace
   where s.nspname = 'public' and c.relkind = 'r' and c.relname like 'khld\_%'
     and c.relname not in ('khld_reference_counter', 'khld_question_list', 'khld_file_field', 'khld_field_rule')
     and (not c.relrowsecurity
          or not exists (select 1 from pg_attribute a where a.attrelid = c.oid and a.attname = 'municipality_id')
          or not exists (select 1 from pg_policy p where p.polrelid = c.oid and p.polcmd = 'r')
          or not exists (select 1 from pg_policy p where p.polrelid = c.oid and p.polcmd = 'a')
          or not exists (select 1 from pg_policy p where p.polrelid = c.oid and p.polcmd = 'w'));
  if v_n <> 0 then raise exception '0160: % tables lack RLS, a policy or municipality_id: %', v_n, v_bad; end if;
  select count(*) into v_n from pg_class c join pg_namespace s on s.oid = c.relnamespace
   where s.nspname = 'public' and c.relkind = 'r' and c.relname like 'khld\_%'
     and c.relname not in ('khld_reference_counter', 'khld_question_list', 'khld_file_field', 'khld_field_rule');
  if v_n <> 30 then raise exception '0160: % khld tables, expected 30', v_n; end if;
  select count(*) into v_n from pg_policy p join pg_class c on c.oid = p.polrelid
   where c.relname like 'khld\_%' and p.polcmd = 'd';
  if v_n <> 7 then raise exception '0160: % DELETE policies, expected 7 (the junctions)', v_n; end if;
  select count(*), string_agg(format('%s.%s', c.conrelid::regclass, c.conname), ', ') into v_n, v_bad
    from pg_constraint c
   where c.contype = 'f' and c.conrelid::regclass::text like 'khld\_%'
     and not exists (select 1 from pg_index i where i.indrelid = c.conrelid and i.indkey[0] = c.conkey[1]);
  if v_n <> 0 then raise exception '0160: unindexed foreign keys: %', v_bad; end if;
  -- the standard triggers are on every table, and the audit trigger on every junction
  select count(*), string_agg(c.relname, ', ') into v_n, v_bad
    from pg_class c join pg_namespace s on s.oid = c.relnamespace
   where s.nspname = 'public' and c.relkind = 'r' and c.relname like 'khld\_%'
     and c.relname not in ('khld_reference_counter', 'khld_question_list', 'khld_file_field', 'khld_field_rule')
     and not exists (select 1 from pg_trigger t where t.tgrelid = c.oid and t.tgname = 'trg_' || c.relname || '_audit');
  if v_n <> 0 then raise exception '0160: tables without an audit trigger: %', v_bad; end if;
end $verify$;
